/**
 * The Banner's mesh glows (Figma renders one pair per layout and line count), inlined as WebP
 * data URIs so they work wherever the component goes: from npm, copied by the shadcn CLI, or in
 * Next.js, with no image files to serve. Each pair is a light glow (drawn in Multiply) and a dark
 * one (in Screen). The glows are soft, so they ship at a quarter of Figma's 2× export (225px
 * wide for a 450px banner) and the browser scales them up: composited, they differ from the
 * full-size renders by under 1/255 on average, at 11 KB for the eight horizontal and sidebar ones
 * instead of 180 KB. Regenerate: export the frames at 2×, resize to 1/4 (Lanczos), WebP quality 85,
 * alpha 90. The inline pair came from a 1.5× export, so it is resized to the same 1/4-of-2× width.
 */
export type Mesh = { light: string; dark: string }

const webp = (base64: string) => `data:image/webp;base64,${base64}`

const horizontal_one_light = webp('')
const horizontal_one_dark = webp('')
const horizontal_two_light = webp('')
const horizontal_two_dark = webp('')
const sidebar_one_light = webp('')
const sidebar_one_dark = webp('')
const sidebar_two_light = webp('')
const sidebar_two_dark = webp('')
// inline: one line across a prompt bar (583 wide). Figma's glow runs taller than the banner, so its
// export keeps that shape (292 × 30 here) and object-cover crops it to the banner, as Figma clips it.
const inline_one_light = webp('')
const inline_one_dark = webp('')

export const bannerMesh: Record<'horizontal' | 'sidebar' | 'inline', Record<'one' | 'two', Mesh>> = {
  horizontal: {
    one: { light: horizontal_one_light, dark: horizontal_one_dark },
    two: { light: horizontal_two_light, dark: horizontal_two_dark },
  },
  sidebar: {
    one: { light: sidebar_one_light, dark: sidebar_one_dark },
    two: { light: sidebar_two_light, dark: sidebar_two_dark },
  },
  // One line only: a description keeps the same glow.
  inline: {
    one: { light: inline_one_light, dark: inline_one_dark },
    two: { light: inline_one_light, dark: inline_one_dark },
  },
}
